116	/** Divide entries em buckets de 7 dias a partir de start até end (inclusive). */
117	export function splitIntoWeeks(
118	  entries: PerdasEntry[],
119	  start: Date,
120	  end: Date,
121	): WeekBucket[] {
122	  const buckets: WeekBucket[] = [];
123	  let cursor = new Date(start);
124	  let index = 1;
125	
126	  while (cursor <= end) {
127	    const bucketStart = new Date(cursor);
128	    const bucketEnd = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));
129	
130	    const bucketEntries = entries.filter(e => {
131	      if (!e.date) return false;
132	      const d = new Date(e.date);
133	      return d >= new Date(bucketStart.setHours(0, 0, 0, 0)) &&
134	             d <= new Date(bucketEnd.setHours(23, 59, 59, 999));
135	    });
136	
137	    // Reset after comparison (setHours mutates)
138	    const bs = new Date(cursor);
139	    const be = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));
140	
141	    const startFmt = format(bs, 'dd/MM', { locale: ptBR });
142	    const endFmt = format(be, 'dd/MM/yyyy', { locale: ptBR });
143	    const trendSubLabel = `${format(bs, 'dd', { locale: ptBR })}-${format(be, 'dd/MM', { locale: ptBR })}`;
144	
145	    buckets.push({
146	      index,
147	      label: `Semana ${index} — ${startFmt} a ${endFmt}`,
148	      trendLabel: `S${index}`,
149	      trendSubLabel,
150	      start: bs,
151	      end: be,
152	      entries: bucketEntries,
153	      aggregate: aggregatePerdas(bucketEntries),
154	    });
155	
156	    cursor = addDays(be, 1);
157	    index++;
158	  }
159	
160	  return buckets;
161	}
