188	/**
189	 * Garante espaço vertical suficiente. Se não couber, vira página e retorna 52.
190	 */
191	function ensureSpace(
192	  doc: jsPDF,
193	  cursorY: number,
194	  neededMm: number,
195	  pageHeight: number,
196	  drawPageExtras: (hookData: { pageNumber?: number }) => void,
197	): number {
198	  if (cursorY + neededMm > pageHeight - 22) {
199	    doc.addPage();
200	    drawPageExtras({ pageNumber: doc.getNumberOfPages() });
201	    return 52;
202	  }
203	  return cursorY;
204	}
