206	/**
207	 * Desenha barras horizontais para uma lista de itens.
208	 * Retorna o Y após o último elemento.
209	 */
210	function drawHorizontalBars(
211	  doc: jsPDF,
212	  items: Array<{ label: string; value: number; displayValue: string }>,
213	  x: number,
214	  y: number,
215	  totalWidth: number,
216	  barHeight = 4.5,
217	  gap = 2.5,
218	  barColor: [number, number, number] = MOMMA_GREEN,
219	): number {
220	  if (items.length === 0) return y;
221	
222	  const maxVal = Math.max(...items.map(i => i.value), 1);
223	  const labelWidth = 30;
224	  const valueWidth = 22;
225	  const barAreaWidth = totalWidth - labelWidth - valueWidth;
226	  let curY = y;
227	
228	  for (const item of items) {
229	    // Label (max 15 chars)
230	    const labelTxt = item.label.length > 15 ? item.label.substring(0, 14) + '…' : item.label;
231	    doc.setFont('helvetica', 'normal');
232	    doc.setFontSize(7);
233	    doc.setTextColor(80, 80, 80);
234	    doc.text(labelTxt, x, curY + barHeight - 1);
235	
236	    const barX = x + labelWidth;
237	
238	    // Background bar
239	    doc.setFillColor(235, 235, 235);
240	    doc.rect(barX, curY, barAreaWidth, barHeight, 'F');
241	
242	    // Colored bar (proportional)
243	    if (item.value > 0) {
244	      const filledW = Math.max(1, (item.value / maxVal) * barAreaWidth);
245	      doc.setFillColor(...barColor);
246	      doc.rect(barX, curY, filledW, barHeight, 'F');
247	    }
248	
249	    // Value label (right)
250	    doc.setFont('helvetica', 'bold');
251	    doc.setFontSize(7);
252	    doc.setTextColor(...MOMMA_GREEN_DARK);
253	    doc.text(item.displayValue, x + totalWidth, curY + barHeight - 1, { align: 'right' });
254	
255	    curY += barHeight + gap;
256	  }
257	
258	  return curY;
259	}
