261	/**
262	 * Desenha barras verticais para dados de tendência.
263	 */
264	function drawVerticalBars(
265	  doc: jsPDF,
266	  items: Array<{ trendLabel: string; trendSubLabel: string; value: number; displayValue: string }>,
267	  x: number,
268	  y: number,
269	  chartWidth: number,
270	  chartHeight: number,
271	  barColor: [number, number, number] = MOMMA_GREEN,
272	): void {
273	  if (items.length === 0) return;
274	
275	  const hasData = items.some(i => i.value > 0);
276	  if (!hasData) return;
277	
278	  const maxVal = Math.max(...items.map(i => i.value), 1);
279	  const n = items.length;
280	  const slotW = chartWidth / n;
281	  const barW = slotW * 0.6;
282	  const axisLabelH = 12; // height reserved below chart for labels
283	  const drawH = chartHeight - axisLabelH;
284	
285	  // Baseline
286	  doc.setDrawColor(200, 200, 200);
287	  doc.setLineWidth(0.3);
288	  doc.line(x, y + drawH, x + chartWidth, y + drawH);
289	
290	  for (let i = 0; i < items.length; i++) {
291	    const item = items[i];
292	    const slotX = x + i * slotW;
293	    const barX = slotX + (slotW - barW) / 2;
294	    const barH = item.value > 0 ? Math.max(1, (item.value / maxVal) * drawH) : 0;
295	    const barY = y + drawH - barH;
296	
297	    // Draw bar
298	    if (barH > 0) {
299	      doc.setFillColor(...barColor);
300	      doc.rect(barX, barY, barW, barH, 'F');
301	    }
302	
303	    // Value label above bar (only if bar is tall enough)
304	    if (barH > 6) {
305	      doc.setFont('helvetica', 'bold');
306	      doc.setFontSize(6);
307	      doc.setTextColor(...MOMMA_GREEN_DARK);
308	      doc.text(item.displayValue, barX + barW / 2, barY - 1, { align: 'center' });
309	    }
310	
311	    // Axis labels below baseline
312	    const labelCenterX = slotX + slotW / 2;
313	    doc.setFont('helvetica', 'bold');
314	    doc.setFontSize(7);
315	    doc.setTextColor(80, 80, 80);
316	    doc.text(item.trendLabel, labelCenterX, y + drawH + 5, { align: 'center' });
317	
318	    doc.setFont('helvetica', 'normal');
319	    doc.setFontSize(6);
320	    doc.setTextColor(120, 120, 120);
321	    doc.text(item.trendSubLabel, labelCenterX, y + drawH + 10, { align: 'center' });
322	  }
323	}
