export interface WeekRange {
  index: number;
  label: string;        // "Semana 1 — 01/05 a 07/05/2026"
  trendLabel: string;   // "S1"
  trendSubLabel: string;// "01-07/05"
  start: Date;
  end: Date;
}

/** Calcula os intervalos semanais (buckets de 7 dias) de start até end (inclusive). */
export function computeWeekRanges(start: Date, end: Date): WeekRange[] {
  const ranges: WeekRange[] = [];
  let cursor = new Date(start);
  let index = 1;

  while (cursor <= end) {
    const bs = new Date(cursor);
    const be = new Date(Math.min(addDays(cursor, 6).getTime(), end.getTime()));

    const startFmt = format(bs, 'dd/MM', { locale: ptBR });
    const endFmt = format(be, 'dd/MM/yyyy', { locale: ptBR });
    const trendSubLabel = `${format(bs, 'dd', { locale: ptBR })}-${format(be, 'dd/MM', { locale: ptBR })}`;

    ranges.push({
      index,
      label: `Semana ${index} — ${startFmt} a ${endFmt}`,
      trendLabel: `S${index}`,
      trendSubLabel,
      start: bs,
      end: be,
    });

    cursor = addDays(be, 1);
    index++;
  }

  return ranges;
}

/** Divide entries em buckets de 7 dias a partir de start até end (inclusive). */
export function splitIntoWeeks(
  entries: PerdasEntry[],
  start: Date,
  end: Date,
): WeekBucket[] {
  return computeWeekRanges(start, end).map(range => {
    const bucketStart = new Date(range.start);
    bucketStart.setHours(0, 0, 0, 0);
    const bucketEnd = new Date(range.end);
    bucketEnd.setHours(23, 59, 59, 999);

    const bucketEntries = entries.filter(e => {
      if (!e.date) return false;
      const d = new Date(e.date);
      return d >= bucketStart && d <= bucketEnd;
    });

    return {
      index: range.index,
      label: range.label,
      trendLabel: range.trendLabel,
      trendSubLabel: range.trendSubLabel,
      start: range.start,
      end: range.end,
      entries: bucketEntries,
      aggregate: aggregatePerdas(bucketEntries),
    };
  });
}

