// ═════════════════════════ RELATÓRIO GERAL · COMPARATIVO DE LOJAS ═════════════════════════

// ───────────────────────── TIPOS PÚBLICOS ─────────────────────────

export interface PerdasGeralEntry {
  val: number;             // valor_estimado
  store: string;           // nome da loja
  loja_id: number | null;
  date: string | null;     // data_identificacao (ISO)
}

export interface GeneratePerdasGeralPdfParams {
  entries: PerdasGeralEntry[];  // TODAS as lojas, filtrado só por período
  periodoLabel: string;
  dateStart: string;            // yyyy-MM-dd
  dateEnd: string;              // yyyy-MM-dd
}

export interface GeralStoreRow {
  store: string;
  value: number;
  count: number;
  pct: number;   // % do total do período (0 se total=0)
}

export interface GeralAggregate {
  totalValue: number;
  totalRecords: number;
  storeCount: number;           // lojas distintas com value > 0
  lojaCritica: string;          // loja de maior valor ("-" se vazio)
  concentracao: number;         // pct da loja crítica
  byStore: GeralStoreRow[];     // ordenado por value desc
}

// ───────────────────────── HELPER PURO (TESTÁVEL) ─────────────────────────

export function aggregateGeral(entries: PerdasGeralEntry[]): GeralAggregate {
  if (entries.length === 0) {
    return {
      totalValue: 0,
      totalRecords: 0,
      storeCount: 0,
      lojaCritica: '-',
      concentracao: 0,
      byStore: [],
    };
  }

  const totalValue = entries.reduce((s, e) => s + e.val, 0);
  const totalRecords = entries.length;

  const storeMap = new Map<string, { value: number; count: number }>();
  for (const e of entries) {
    const name = e.store && e.store.trim() ? e.store : 'Sem loja';
    const cur = storeMap.get(name) ?? { value: 0, count: 0 };
    storeMap.set(name, { value: cur.value + e.val, count: cur.count + 1 });
  }

  const byStore: GeralStoreRow[] = Array.from(storeMap.entries())
    .map(([store, d]) => ({
      store,
      value: d.value,
      count: d.count,
      pct: totalValue > 0 ? (d.value / totalValue) * 100 : 0,
    }))
    .sort((a, b) => b.value - a.value);

  const storeCount = byStore.filter(s => s.value > 0).length;
  const lojaCritica = byStore.length > 0 ? byStore[0].store : '-';
  const concentracao = byStore.length > 0 ? byStore[0].pct : 0;

  return {
    totalValue,
    totalRecords,
    storeCount,
    lojaCritica,
    concentracao,
    byStore,
  };
}

/** Filtra entries cujo `date` cai dentro do range [start, end] (dia inteiro). */
function entriesInRange(entries: PerdasGeralEntry[], start: Date, end: Date): PerdasGeralEntry[] {
  const s = new Date(start); s.setHours(0, 0, 0, 0);
  const e = new Date(end); e.setHours(23, 59, 59, 999);
  return entries.filter(en => {
    if (!en.date) return false;
    const d = new Date(en.date);
    return d >= s && d <= e;
  });
}

// ───────────────────────── HELPER DE BARRAS POR LOJA ─────────────────────────

/**
 * Desenha barras horizontais comparando lojas (valor + % dentro da barra).
 * Retorna o Y após o último item.
 */
function drawStoreBars(
  doc: jsPDF,
  items: Array<{ store: string; value: number; pct: number }>,
  x: number,
  y: number,
  totalWidth: number,
  barHeight = 5.5,
  gap = 3,
): number {
  if (items.length === 0) return y;

  const maxVal = Math.max(...items.map(i => i.value), 1);
  const labelWidth = 40;
  const valueWidth = 28;
  const barArea = totalWidth - labelWidth - valueWidth;
  let curY = y;

  for (const item of items) {
    // Label (nome da loja, max 22 chars)
    const labelTxt = item.store.length > 22 ? item.store.substring(0, 21) + '…' : item.store;
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(7.5);
    doc.setTextColor(70, 70, 70);
    doc.text(labelTxt, x, curY + barHeight - 1.5);

    const barX = x + labelWidth;

    // Background bar
    doc.setFillColor(235, 235, 235);
    doc.rect(barX, curY, barArea, barHeight, 'F');

    if (item.value > 0) {
      const filledW = Math.max(1, (item.value / maxVal) * barArea);
      doc.setFillColor(...MOMMA_GREEN);
      doc.rect(barX, curY, filledW, barHeight, 'F');

      const pctTxt = pctFmt(item.pct);
      if (filledW >= 14) {
        // % dentro da barra, branco, centralizado
        doc.setFont('helvetica', 'bold');
        doc.setFontSize(7);
        doc.setTextColor(255, 255, 255);
        doc.text(pctTxt, barX + filledW / 2, curY + barHeight / 2 + 1, { align: 'center' });
      } else {
        // % logo após a barra preenchida
        doc.setFont('helvetica', 'normal');
        doc.setFontSize(7);
        doc.setTextColor(...MOMMA_GREEN_DARK);
        doc.text(pctTxt, barX + filledW + 1.5, curY + barHeight - 1.5);
      }
    }

    // Valor R$ à direita
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(7.5);
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.text(currencyFmt(item.value), x + totalWidth, curY + barHeight - 1.5, { align: 'right' });

    curY += barHeight + gap;
  }

  return curY;
}

// ───────────────────────── GERADOR DE PDF GERAL ─────────────────────────

export async function generatePerdasGeralPdf(params: GeneratePerdasGeralPdfParams): Promise<void> {
  const { entries, periodoLabel, dateStart, dateEnd } = params;
  const agg = aggregateGeral(entries);

  const logoHeader = await loadImage('/logo sistema/01. Reduzida 5.png').catch(() => null);
  const watermarkLogo = await loadImage('/logo sistema/android-chrome-512x512.png').catch(() => null);

  const doc = new jsPDF('p', 'mm', 'a4');
  const pageWidth = doc.internal.pageSize.getWidth();
  const pageHeight = doc.internal.pageSize.getHeight();

  // ───────────────────────── HEADER, FOOTER & WATERMARK POR PÁGINA ─────────────────────────
  const drawPageExtras = (hookData: { pageNumber?: number }) => {
    const currentPage = hookData.pageNumber || 1;

    // Bordas premium (dupla linha)
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.roundedRect(10, 10, pageWidth - 20, pageHeight - 20, 2, 2, 'S');
    doc.setLineWidth(0.2);
    doc.roundedRect(12, 12, pageWidth - 24, pageHeight - 24, 2, 2, 'S');

    // Logo cabeçalho — preserva aspect ratio, max 18mm altura
    if (logoHeader) {
      const ratio = logoHeader.height / logoHeader.width;
      let expectedWidth = 45;
      let expectedHeight = expectedWidth * ratio;
      if (expectedHeight > 18) {
        expectedHeight = 18;
        expectedWidth = expectedHeight / ratio;
      }
      doc.addImage(logoHeader, 'PNG', 15, 15, expectedWidth, expectedHeight);
    }

    // Título e subtítulo (alinhados à direita)
    doc.setFont('helvetica', 'bold');
    doc.setTextColor(...MOMMA_GREEN_DARK);
    doc.setFontSize(16);
    doc.text('RELATÓRIO GERAL DE PERDAS', pageWidth - 15, 20, { align: 'right' });

    doc.setFont('helvetica', 'normal');
    doc.setFontSize(9);
    doc.setTextColor(...MOMMA_GREEN);
    doc.text('VISÃO MACRO · COMPARATIVO DE LOJAS', pageWidth - 15, 25, { align: 'right' });

    doc.setTextColor(...MOMMA_GREEN_SOFT);
    doc.setFontSize(8);
    doc.text(`Período: ${periodoLabel}`, pageWidth - 15, 31, { align: 'right' });
    doc.text('Loja: Todas as lojas', pageWidth - 15, 35, { align: 'right' });

    // Linha separadora abaixo do header
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.5);
    doc.line(15, 43, pageWidth - 15, 43);

    // Footer com paginação
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(...MOMMA_GREEN);
    const totalPages = doc.getNumberOfPages();
    doc.text(
      `Relatório Geral de Perdas Momma • Emissão: ${format(new Date(), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })} • Pág. ${currentPage}/${totalPages}`,
      pageWidth / 2,
      pageHeight - 12,
      { align: 'center' },
    );

    // Watermark sutil ao centro
    if (watermarkLogo) {
      try {
        doc.setGState(new GState({ opacity: 0.08 }));
        const wSize = 200;
        doc.addImage(
          watermarkLogo,
          'PNG',
          (pageWidth - wSize) / 2,
          (pageHeight - wSize) / 2,
          wSize,
          wSize,
        );
        doc.setGState(new GState({ opacity: 1.0 }));
      } catch {
        /* fallback silencioso */
      }
    }
  };

  // Página 1: header desenhado manualmente
  drawPageExtras({ pageNumber: 1 });

  // ───────────────────────── RESUMO EXECUTIVO ─────────────────────────
  let cursorY = 52;

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('RESUMO EXECUTIVO DO PERÍODO', 15, cursorY);
  cursorY += 5;

  const boxX = 15;
  const boxW = pageWidth - 30;
  const boxH = 22;

  doc.setFillColor(248, 250, 248);
  doc.setDrawColor(...MOMMA_GREEN);
  doc.setLineWidth(0.4);
  doc.roundedRect(boxX, cursorY, boxW, boxH, 2, 2, 'FD');

  const colW = boxW / 4;

  const drawMetric = (label: string, value: string, colIndex: number) => {
    doc.setFont('helvetica', 'normal');
    doc.setFontSize(8);
    doc.setTextColor(120, 120, 120);
    doc.text(label, boxX + colW * colIndex + 4, cursorY + 6);
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(11);
    doc.setTextColor(...MOMMA_GREEN_DARK);
    const maxWidth = colW - 8;
    const truncated = doc.getStringUnitWidth(value) * 11 / doc.internal.scaleFactor > maxWidth
      ? value.substring(0, 18) + '…'
      : value;
    doc.text(truncated, boxX + colW * colIndex + 4, cursorY + 14);
  };

  drawMetric('PREJUÍZO TOTAL', currencyFmt(agg.totalValue), 0);
  drawMetric('LOJAS ATIVAS', String(agg.storeCount), 1);
  const critLabel = agg.lojaCritica.length > 18
    ? agg.lojaCritica.substring(0, 18) + '…'
    : agg.lojaCritica;
  drawMetric('LOJA CRÍTICA', critLabel, 2);
  drawMetric('CONCENTRAÇÃO', pctFmt(agg.concentracao), 3);

  cursorY += boxH + 8;

  // ───────────────────────── TENDÊNCIA SEMANAL ─────────────────────────
  const weeks = computeWeekRanges(
    new Date(dateStart + 'T00:00:00'),
    new Date(dateEnd + 'T00:00:00'),
  );

  const weekTotals = weeks.map(w => {
    const wEntries = entriesInRange(entries, w.start, w.end);
    return wEntries.reduce((s, e) => s + e.val, 0);
  });

  cursorY = ensureSpace(doc, cursorY, 55, pageHeight, drawPageExtras);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('TENDÊNCIA SEMANAL', 15, cursorY);
  cursorY += 3;

  const trendData = weeks.map((w, i) => ({
    trendLabel: w.trendLabel,
    trendSubLabel: w.trendSubLabel,
    value: weekTotals[i],
    displayValue: weekTotals[i] > 0 ? currencyFmt(weekTotals[i]) : 'R$ 0',
  }));

  drawVerticalBars(doc, trendData, 15, cursorY, pageWidth - 30, 38);
  cursorY += 38 + 12 + 10;

  // ───────────────────────── RANKING DE LOJAS (PERÍODO) ─────────────────────────
  cursorY = ensureSpace(doc, cursorY, 20 + agg.byStore.length * 8.5, pageHeight, drawPageExtras);

  doc.setFont('helvetica', 'bold');
  doc.setFontSize(11);
  doc.setTextColor(...MOMMA_GREEN);
  doc.text('RANKING DE LOJAS · PERÍODO', 15, cursorY);
  cursorY += 4;

  cursorY = drawStoreBars(
    doc,
    agg.byStore.map(s => ({ store: s.store, value: s.value, pct: s.pct })),
    15,
    cursorY,
    pageWidth - 30,
  );
  cursorY += 8;

  // ───────────────────────── SEÇÕES POR SEMANA ─────────────────────────
  for (let wi = 0; wi < weeks.length; wi++) {
    const week = weeks[wi];
    const weekEntries = entriesInRange(entries, week.start, week.end);
    const wAgg = aggregateGeral(weekEntries);
    const prevTotal = wi > 0
      ? entriesInRange(entries, weeks[wi - 1].start, weeks[wi - 1].end).reduce((s, e) => s + e.val, 0)
      : 0;

    cursorY = ensureSpace(doc, cursorY, 50, pageHeight, drawPageExtras);

    // Cabeçalho verde da semana
    doc.setFillColor(...MOMMA_GREEN);
    doc.rect(15, cursorY, pageWidth - 30, 7, 'F');
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(9);
    doc.setTextColor(255, 255, 255);
    doc.text(week.label, pageWidth / 2, cursorY + 5, { align: 'center' });
    cursorY += 7 + 3;

    // KPIs compactos da semana (caixa 18mm)
    const wBoxH = 18;
    doc.setFillColor(248, 250, 248);
    doc.setDrawColor(...MOMMA_GREEN);
    doc.setLineWidth(0.3);
    doc.roundedRect(15, cursorY, pageWidth - 30, wBoxH, 2, 2, 'FD');

    const wColW = (pageWidth - 30) / 4;

    const drawWeekMetric = (label: string, value: string, colIndex: number) => {
      const mx = 15 + wColW * colIndex + 3;
      doc.setFont('helvetica', 'normal');
      doc.setFontSize(7);
      doc.setTextColor(120, 120, 120);
      doc.text(label, mx, cursorY + 5);
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(10);
      doc.setTextColor(...MOMMA_GREEN_DARK);
      const maxW = wColW - 6;
      const txt = doc.getStringUnitWidth(value) * 10 / doc.internal.scaleFactor > maxW
        ? value.substring(0, 14) + '…'
        : value;
      doc.text(txt, mx, cursorY + 12);
    };

    const wCritico = wAgg.lojaCritica.length > 14
      ? wAgg.lojaCritica.substring(0, 14) + '…'
      : wAgg.lojaCritica;

    drawWeekMetric('PREJUÍZO', currencyFmt(wAgg.totalValue), 0);
    drawWeekMetric('LOJAS ATIVAS', String(wAgg.storeCount), 1);
    drawWeekMetric('LOJA LÍDER', wCritico, 2);
    drawWeekMetric('CONCENTRAÇÃO', pctFmt(wAgg.concentracao), 3);

    // Delta em relação à semana anterior (apenas no prejuízo)
    if (wi > 0 && prevTotal > 0) {
      const delta = ((wAgg.totalValue - prevTotal) / prevTotal) * 100;
      const isImproved = delta < 0; // perda menor = melhora
      const deltaText = (isImproved ? '▼ ' : '▲ ') + Math.abs(delta).toFixed(1) + '%';
      doc.setFont('helvetica', 'bold');
      doc.setFontSize(7);
      doc.setTextColor(...(isImproved ? ([34, 197, 94] as [number, number, number]) : ([239, 68, 68] as [number, number, number])));
      doc.text(deltaText, 15 + 3, cursorY + 17);
    }

    cursorY += wBoxH + 4;

    // POR LOJA (barras de loja da semana, largura cheia)
    doc.setFont('helvetica', 'bold');
    doc.setFontSize(8);
    doc.setTextColor(...MOMMA_GREEN);
    doc.text('POR LOJA', 15, cursorY + 4);

    const barsNeeded = wAgg.byStore.length * (5.5 + 3) + 12;
    cursorY = ensureSpace(doc, cursorY, barsNeeded, pageHeight, drawPageExtras);

    cursorY = drawStoreBars(
      doc,
      wAgg.byStore.map(s => ({ store: s.store, value: s.value, pct: s.pct })),
      15,
      cursorY + 6,
      pageWidth - 30,
    );
    cursorY += 8;
  }

  // ───────────────────────── PERSISTÊNCIA ─────────────────────────
  const slug = periodoLabel.replace(/[^a-zA-Z0-9]/g, '_');
  doc.save(`perdas_geral_${slug}.pdf`);
}

